"use client";

import type { ReactNode } from "react";
import { useDataGridUrlState, type UseDataGridUrlStateOptions } from "./use-data-grid-url-state";

/** Public entry point — the only module consumers/docs should import from. */
export {
  useDataGridUrlState,
  type UseDataGridUrlStateOptions,
  type UseDataGridUrlStateResult,
} from "./use-data-grid-url-state";
export type { UrlLayoutPart } from "./layout-param";
export {
  useDataGridUrlPagination,
  type UseDataGridUrlPaginationOptions,
  type UseDataGridUrlPaginationResult,
} from "./use-data-grid-url-pagination";

/** Props for {@link DataGridUrlState}. */
export type DataGridUrlStateProps = UseDataGridUrlStateOptions;

/**
 * Renders nothing; syncs the grid's sort/filter/search state with the URL (see
 * {@link useDataGridUrlState}). Mount it once inside `<DataGridProvider>`, alongside
 * `<DataGridRoot>`/`<DataGridToolbar>`. Requires a nuqs adapter (`NuqsAdapter` from
 * `nuqs/adapters/react`, or your framework's) somewhere above it in the tree.
 *
 * @example
 * <DataGridProvider data={rows} columns={columns} getRowId={(r) => r.id}>
 *   <DataGridUrlState prefix="orders" />
 *   <DataGridToolbar><DataGridSearch /></DataGridToolbar>
 *   <DataGridRoot>...</DataGridRoot>
 * </DataGridProvider>
 */
export function DataGridUrlState(props: DataGridUrlStateProps): ReactNode {
  useDataGridUrlState(props);
  return null;
}

import type { FilterOperator } from "@/registry/default/components/data-grid/data-grid";

/** The closed set of valid {@link FilterOperator} values, for validating URL input against. */
export const FILTER_OPERATORS: ReadonlySet<FilterOperator> = new Set([
  "contains",
  "notContains",
  "equals",
  "notEquals",
  "startsWith",
  "endsWith",
  "empty",
  "notEmpty",
  "gt",
  "gte",
  "lt",
  "lte",
  "isBetween",
  "isAnyOf",
  "isNoneOf",
] satisfies FilterOperator[]);

/** Narrows an untrusted (URL-decoded) string to {@link FilterOperator}. */
export function isFilterOperator(value: string): value is FilterOperator {
  return FILTER_OPERATORS.has(value as FilterOperator);
}

import type { FilterOperator, FilterSpec } from "@/registry/default/components/data-grid/data-grid";
import { isFilterOperator } from "./filter-operators";
import { safeDecode } from "./sort-param";

/** In-value separator for `isBetween`'s two-part value. `encodeURIComponent` leaves `~` in its unreserved set untouched, so a literal `~` inside a bound must be escaped separately (see {@link encodeRangePart}) to stay unambiguous against the separator. */
const RANGE_SEPARATOR = "~";

/** In-value separator for the `isAnyOf` and `isNoneOf` choice lists. `encodeURIComponent` escapes a literal `|` inside a choice to `%7C`, so the raw separator can never collide with a choice's own characters. */
const ANYOF_SEPARATOR = "|";

/** Token for an empty list entry (the "(Blanks)" value). `encodeURIComponent` never emits a lone `%`, so no encoded value collides with it, and a sole empty entry stays distinct from an empty list. */
const EMPTY_ENTRY_TOKEN = "%";

/** A hand-edited URL must not express an unbounded view state; filter segments beyond the cap are dropped. */
const MAX_URL_FILTERS = 64;

/** Raw comma-separated segments read before parsing stops; bounds the work a URL of empty segments can cost. */
const MAX_URL_FILTER_SEGMENTS = MAX_URL_FILTERS * 4;

/** Bound for one `isAnyOf` or `isNoneOf` list parsed from a URL when the caller names no per-column limit. */
const DEFAULT_MAX_ANYOF_CHOICES = 1000;

/** Options for {@link parseFilterState}. */
export type ParseFilterStateOptions = {
  /** Most entries an `isAnyOf` or `isNoneOf` list of this column may hold, usually its number of `choices`. Returns `undefined` for the 1000 default. */
  maxChoices?: (columnId: string) => number | undefined;
};

/** `encodeURIComponent` plus escaping the one character it doesn't (`~`), so a literal tilde in a bound never collides with {@link RANGE_SEPARATOR}. */
function encodeRangePart(part: string): string {
  return encodeURIComponent(part).replace(/~/g, "%7E");
}

function encodeFilterValue(operator: FilterOperator, value: FilterSpec["value"]): string {
  if (value === undefined) return "";
  if (Array.isArray(value) && operator === "isBetween") return `${encodeRangePart(value[0])}${RANGE_SEPARATOR}${encodeRangePart(value[1])}`;
  if (Array.isArray(value)) return value.map((entry) => (entry === "" ? EMPTY_ENTRY_TOKEN : encodeURIComponent(entry))).join(ANYOF_SEPARATOR);
  return encodeURIComponent(value);
}

/**
 * Compact URL encoding for {@link FilterSpec}[]: comma-separated `columnId:operator:value` triples
 * (`value` omitted for operators with none, e.g. `empty`/`notEmpty`), column id and value
 * percent-encoded. `isBetween`'s two-value range encodes as `min~max`, the `isAnyOf` and `isNoneOf` choice lists as
 * `a|b|c` (each choice percent-encoded, so the raw `|` separator can never collide) — both still
 * one `value` field, so every other operator's format — and any URL generated before those
 * operators existed — round-trips unchanged. An empty list entry encodes as the lone token `%`
 * (`a|%`), so `[""]` differs from `[]`; a part left empty by hand-editing still reads as an empty entry. `filterId` is never serialized — it's a transient
 * list-rendering identity the store re-derives on parse, not part of the filter's meaning.
 *
 * @example serializeFilterState([{ columnId: "age", operator: "gt", value: "30" }])
 * // => "age:gt:30"
 * @example serializeFilterState([{ columnId: "name", operator: "empty" }])
 * // => "name:empty:"
 * @example serializeFilterState([{ columnId: "age", operator: "isBetween", value: ["10", "30"] }])
 * // => "age:isBetween:10~30"
 * @example serializeFilterState([{ columnId: "status", operator: "isAnyOf", value: ["new", "open"] }])
 * // => "status:isAnyOf:new|open"
 */
export function serializeFilterState(filters: readonly FilterSpec[]): string {
  return filters.map((f) => `${encodeURIComponent(f.columnId)}:${f.operator}:${encodeFilterValue(f.operator, f.value)}`).join(",");
}

/** Sentinel distinguishing "decode failed, drop the segment" from a legitimately-empty decoded value (`""`). */
const DECODE_FAILED = Symbol("decode-failed");

/** Decodes a segment's value part per `operator`: `isBetween` splits on {@link RANGE_SEPARATOR} into a tuple, `isAnyOf` and `isNoneOf` split on {@link ANYOF_SEPARATOR} into a choice list (empty value = empty list), everything else stays a plain string. Malformed input (wrong tuple arity, bad percent-encoding) returns {@link DECODE_FAILED}. */
function decodeFilterValue(operator: string, raw: string, maxChoices: number): FilterSpec["value"] | typeof DECODE_FAILED {
  if (operator === "isAnyOf" || operator === "isNoneOf") {
    if (raw === "") return [];
    const parts: string[] = [];
    for (const rawPart of raw.split(ANYOF_SEPARATOR)) {
      if (parts.length >= maxChoices) {
        // a truncated exclusion list would match more rows than the link meant
        if (operator === "isNoneOf") return DECODE_FAILED;
        break;
      }
      const decoded = rawPart === EMPTY_ENTRY_TOKEN ? "" : safeDecode(rawPart);
      if (decoded === null) return DECODE_FAILED;
      parts.push(decoded);
    }
    return parts;
  }
  if (operator !== "isBetween") {
    const decoded = safeDecode(raw);
    return decoded === null ? DECODE_FAILED : decoded;
  }
  const parts = raw.split(RANGE_SEPARATOR);
  if (parts.length !== 2) return DECODE_FAILED;
  const [min, max] = parts.map(safeDecode);
  if (min == null || max == null) return DECODE_FAILED;
  return [min, max];
}

/**
 * Inverse of {@link serializeFilterState}. Malformed segments (unknown operator, empty/undecodable
 * column id, wrong field count, malformed `isBetween` range or `isAnyOf` / `isNoneOf` list) are dropped silently
 * rather than throwing — a corrupt/hand-edited URL degrades to fewer filters, never an error.
 * Parsing stops after 256 raw segments. The parsed list is capped at 64 filters, and each `isAnyOf`
 * list at `options.maxChoices(columnId)` entries (1000 by default); the first segments win, so a
 * hand-edited URL cannot express an unbounded filter set. An `isNoneOf` list over its bound drops
 * the whole segment.
 * Every filter parses without a `filterId`; the store backfills a fresh stable one on the next sync.
 *
 * @example parseFilterState("age:gt:30") // => [{ columnId: "age", operator: "gt", value: "30" }]
 * @example parseFilterState("name:empty:") // => [{ columnId: "name", operator: "empty", value: "" }]
 * @example parseFilterState("age:isBetween:10~30") // => [{ columnId: "age", operator: "isBetween", value: ["10", "30"] }]
 * @example parseFilterState("status:isAnyOf:new|open") // => [{ columnId: "status", operator: "isAnyOf", value: ["new", "open"] }]
 * @example parseFilterState("garbage") // => []
 */
export function parseFilterState(raw: string, options: ParseFilterStateOptions = {}): FilterSpec[] {
  if (!raw) return [];
  const filters: FilterSpec[] = [];
  let start = 0;
  for (let read = 0; read < MAX_URL_FILTER_SEGMENTS && start <= raw.length && filters.length < MAX_URL_FILTERS; read++) {
    const comma = raw.indexOf(",", start);
    const end = comma === -1 ? raw.length : comma;
    const segment = raw.slice(start, end);
    start = end + 1;
    const parts = segment.split(":");
    if (parts.length !== 3) continue;
    const [columnId, operator, rawValue] = parts;
    if (!columnId || operator === undefined || rawValue === undefined || !isFilterOperator(operator)) continue;
    const decodedId = safeDecode(columnId);
    if (decodedId === null || decodedId === "") continue;
    const value = decodeFilterValue(operator, rawValue, options.maxChoices?.(decodedId) ?? DEFAULT_MAX_ANYOF_CHOICES);
    if (value === DECODE_FAILED) continue;
    filters.push({ columnId: decodedId, operator, value });
  }
  return filters;
}

import type { FilterJoinOperator } from "@/registry/default/components/data-grid/data-grid";

/**
 * URL encoding for {@link FilterJoinOperator}: the literal value itself, no extra structure needed.
 * A separate `join` param (not folded into `filter`) so an "and"-only URL from before this feature
 * existed keeps parsing identically — {@link parseJoinOperator} treats an absent/malformed param the
 * same as `"and"`, the pre-existing default.
 *
 * @example serializeJoinOperator("or") // => "or"
 * @example serializeJoinOperator("and") // => "" (the default; omitted from the URL)
 */
export function serializeJoinOperator(joinOperator: FilterJoinOperator): string {
  return joinOperator === "or" ? "or" : "";
}

/**
 * Inverse of {@link serializeJoinOperator}. Anything other than exactly `"or"` (absent, empty,
 * hand-edited garbage) parses as `"and"` — never throws.
 *
 * @example parseJoinOperator("or") // => "or"
 * @example parseJoinOperator("") // => "and"
 * @example parseJoinOperator("garbage") // => "and"
 */
export function parseJoinOperator(raw: string): FilterJoinOperator {
  return raw === "or" ? "or" : "and";
}

import type { ColumnLayout } from "@/registry/default/components/data-grid/data-grid";
import { safeDecode } from "./sort-param";

/** The parts of a {@link ColumnLayout} the URL can carry. */
export type UrlLayoutPart = "order" | "hidden" | "widths" | "pins";

/** Segments read from one layout param; a forged link cannot allocate past it. */
export const MAX_URL_LAYOUT_COLUMNS = 1024;

/** A layout param longer than this is ignored as a whole. */
export const MAX_URL_LAYOUT_PARAM_LENGTH = 16_384;

const NONE = "-";
const WIDTH_PATTERN = /^\d{1,5}$/;

function encodeId(id: string): string {
  return id === NONE ? "%2D" : encodeURIComponent(id);
}

function serializePair(id: string, value: string | number): string {
  return `${encodeId(id)}:${value}`;
}

/**
 * Compact URL encoding of one {@link ColumnLayout} part: `order` and `hidden` are comma-separated
 * column ids, `widths` is `id:px` pairs, `pins` is `id:l` / `id:r` pairs. Ids are percent-encoded.
 * An empty `hidden` or `pins` part is written as `-`.
 *
 * @example serializeLayoutPart("widths", { ...layout, widths: { name: 240 } }) // => "name:240"
 */
export function serializeLayoutPart(part: UrlLayoutPart, layout: ColumnLayout): string {
  switch (part) {
    case "order":
      return layout.order.map(encodeId).join(",");
    case "hidden":
      return layout.hidden.length === 0 ? NONE : layout.hidden.map(encodeId).join(",");
    case "widths":
      return Object.entries(layout.widths)
        .map(([id, width]) => serializePair(id, Math.round(width)))
        .join(",");
    case "pins": {
      const pins = Object.entries(layout.pins);
      return pins.length === 0 ? NONE : pins.map(([id, side]) => serializePair(id, side === "left" ? "l" : "r")).join(",");
    }
    default:
      return "";
  }
}

function decodeId(raw: string): string | null {
  const id = raw === "" ? null : safeDecode(raw);
  return id === "" ? null : id;
}

function parseIds(raw: string): string[] {
  const seen = new Set<string>();
  for (const segment of raw.split(",", MAX_URL_LAYOUT_COLUMNS)) {
    const id = decodeId(segment);
    if (id !== null) seen.add(id);
  }
  return [...seen];
}

function parsePairs<V>(raw: string, parseValue: (value: string) => V | null): [string, V][] {
  const seen = new Set<string>();
  const pairs: [string, V][] = [];
  for (const segment of raw.split(",", MAX_URL_LAYOUT_COLUMNS)) {
    const colon = segment.indexOf(":");
    if (colon < 0 || segment.indexOf(":", colon + 1) >= 0) continue;
    const id = decodeId(segment.slice(0, colon));
    if (id === null || seen.has(id)) continue;
    const value = parseValue(segment.slice(colon + 1));
    if (value === null) continue;
    seen.add(id);
    pairs.push([id, value]);
  }
  return pairs;
}

/**
 * Inverse of {@link serializeLayoutPart}. Returns only the given part, or `{}` when the param is
 * empty, longer than {@link MAX_URL_LAYOUT_PARAM_LENGTH}, or holds nothing valid. Reads at most
 * {@link MAX_URL_LAYOUT_COLUMNS} segments; undecodable, empty, and repeated ids and malformed values
 * are dropped (the first segment of an id wins). Never throws.
 *
 * @example parseLayoutPart("pins", "name:l,age:r") // => { pins: { name: "left", age: "right" } }
 */
export function parseLayoutPart(part: UrlLayoutPart, raw: string): Partial<ColumnLayout> {
  if (raw === "" || raw.length > MAX_URL_LAYOUT_PARAM_LENGTH) return {};
  switch (part) {
    case "order":
      return { order: parseIds(raw) };
    case "hidden":
      return { hidden: raw === NONE ? [] : parseIds(raw) };
    case "widths":
      return { widths: Object.fromEntries(parsePairs(raw, (v) => (WIDTH_PATTERN.test(v) ? Number(v) : null))) };
    case "pins":
      return {
        pins: Object.fromEntries(parsePairs(raw, (v) => (v === "l" ? "left" : v === "r" ? "right" : null))) as ColumnLayout["pins"],
      };
    default:
      return {};
  }
}

/** Default `pageSize` when {@link UseDataGridUrlPaginationOptions.defaultPageSize} is not given. */
export const DEFAULT_URL_PAGE_SIZE = 25;

/** Absolute ceiling for the URL `page` param: a page number beyond it is a typo or an attack, and parses as 1 like any other invalid value. */
export const MAX_URL_PAGE = 1_000_000;

/**
 * URL encoding for the 1-based `page` number: the plain decimal string, omitted entirely when
 * `page` is 1 (the default), matching `join`'s omit-at-default convention.
 *
 * @example serializePage(1) // => "" (the default; omitted from the URL)
 * @example serializePage(3) // => "3"
 */
export function serializePage(page: number): string {
  return page <= 1 ? "" : String(page);
}

/**
 * Inverse of {@link serializePage}. Anything that isn't a positive integer (absent, empty,
 * negative, fractional, hand-edited garbage) parses as `1` — never throws.
 *
 * @example parsePage("3") // => 3
 * @example parsePage("") // => 1
 * @example parsePage("garbage") // => 1
 */
export function parsePage(raw: string): number {
  const n = Number(raw);
  return raw !== "" && Number.isInteger(n) && n >= 1 && n <= MAX_URL_PAGE ? n : 1;
}

/**
 * URL encoding for `pageSize`: the plain decimal string, omitted when it equals `defaultPageSize`.
 *
 * @example serializePageSize(25, 25) // => "" (matches the default; omitted from the URL)
 * @example serializePageSize(50, 25) // => "50"
 */
export function serializePageSize(pageSize: number, defaultPageSize: number): string {
  return pageSize === defaultPageSize ? "" : String(pageSize);
}

/**
 * Inverse of {@link serializePageSize}. Falls back to `defaultPageSize` for anything that isn't a
 * positive integer. When `allowedSizes` is given, a parsed value outside that list also falls back
 * to `defaultPageSize` — the URL cannot force a page size the consumer didn't offer.
 *
 * @example parsePageSize("50", 25) // => 50
 * @example parsePageSize("", 25) // => 25
 * @example parsePageSize("999", 25, [10, 25, 50]) // => 25 (not in the allowed list)
 */
export function parsePageSize(raw: string, defaultPageSize: number, allowedSizes?: readonly number[]): number {
  const n = Number(raw);
  if (raw === "" || !Number.isInteger(n) || n < 1) return defaultPageSize;
  if (allowedSizes && !allowedSizes.includes(n)) return defaultPageSize;
  return n;
}

/** Namespaces a URL param key for multi-grid pages, e.g. `prefixedKey("orders", "sort")` => `"orders_sort"`. */
export function prefixedKey(prefix: string | undefined, key: string): string {
  return prefix ? `${prefix}_${key}` : key;
}

import type { SortSpec } from "@/registry/default/components/data-grid/data-grid";

/** A hand-edited URL must not express an unbounded sort list; segments beyond the cap are dropped. */
const MAX_URL_SORTS = 64;

/** Raw segments read from the param, so a forged link of millions of commas allocates nothing past this. */
const MAX_URL_SORT_SEGMENTS = 256;

/**
 * Compact URL encoding for {@link SortSpec}[]: comma-separated `columnId:direction` pairs,
 * column id percent-encoded (ids are consumer-controlled and may contain `,`/`:`).
 *
 * @example serializeSortState([{ columnId: "name", direction: "asc" }, { columnId: "age", direction: "desc" }])
 * // => "name:asc,age:desc"
 */
export function serializeSortState(sorts: readonly SortSpec[]): string {
  return sorts.map((s) => `${encodeURIComponent(s.columnId)}:${s.direction}`).join(",");
}

/** `decodeURIComponent` throws on malformed `%` sequences a hand-edited URL can contain — never let that surface. */
export function safeDecode(value: string): string | null {
  try {
    return decodeURIComponent(value);
  } catch {
    return null;
  }
}

/**
 * Inverse of {@link serializeSortState}. Malformed segments (missing direction, bad direction
 * value, empty/undecodable column id) are dropped silently rather than throwing — a corrupt/hand-edited
 * URL degrades to fewer sorts, never an error. A column id repeated in the URL yields one sort entry
 * (the first segment wins), matching the grid's one-direction-per-column sort model. The parsed
 * list is capped at 64 sorts.
 *
 * @example parseSortState("name:asc,age:desc") // => [{ columnId: "name", direction: "asc" }, { columnId: "age", direction: "desc" }]
 * @example parseSortState("garbage") // => []
 */
export function parseSortState(raw: string): SortSpec[] {
  if (!raw) return [];
  const sorts: SortSpec[] = [];
  // one sort entry per column (the grid's sort model) — a repeated column id keeps its first segment
  const seenColumns = new Set<string>();
  for (const segment of raw.split(",", MAX_URL_SORT_SEGMENTS)) {
    if (sorts.length >= MAX_URL_SORTS) break;
    const [columnId, direction] = segment.split(":");
    if (!columnId || (direction !== "asc" && direction !== "desc")) continue;
    const decoded = safeDecode(columnId);
    if (decoded === null || decoded === "") continue;
    if (seenColumns.has(decoded)) continue;
    seenColumns.add(decoded);
    sorts.push({ columnId: decoded, direction });
  }
  return sorts;
}

"use client";

import { useCallback, useEffect, useMemo, useRef } from "react";
import { useQueryState } from "nuqs";
import { clampPage, DEFAULT_PAGE_SIZES } from "@/registry/default/components/data-grid-pagination/data-grid-pagination";
import { parsePage, parsePageSize, serializePage, serializePageSize, DEFAULT_URL_PAGE_SIZE } from "./page-param";
import { prefixedKey } from "./prefixed-key";

/** Options for {@link useDataGridUrlPagination}. */
export type UseDataGridUrlPaginationOptions = {
  /** Namespaces the `page`/`pageSize` URL keys so multiple grids can coexist on one page. */
  prefix?: string;
  /** `pageSize` this many is omitted from the URL. Also the fallback for an invalid URL value. Default 25. */
  defaultPageSize?: number;
  /** When given, a `pageSize` URL value outside this list falls back to `defaultPageSize` instead of being trusted. */
  pageSizeOptions?: readonly number[];
  /** The dataset's row count; when given, an out-of-range deep-linked `page` is clamped to the last page and the clamped value is written back to the URL. A 0 total (data loading) suspends both until a positive total arrives. */
  total?: number;
};

/** Controlled pair spread straight into `useDataGridPagination`'s server mode. */
export type UseDataGridUrlPaginationResult = {
  page: number;
  pageSize: number;
  /** The `pageSizeOptions` the URL parsing enforces (`pageSizeOptions` or the pager default) — include it so the bar's select and the URL allow-list never diverge. */
  pageSizeOptions: readonly number[];
  onPageChange: (page: number) => void;
  onPageSizeChange: (pageSize: number) => void;
};

/**
 * Syncs `page`/`pageSize` with the URL via nuqs, no dependency on `data-grid-pagination` or the
 * grid's store — pagination has no store slot, so this hook just owns two URL-backed numbers and
 * hands back the controlled pair `useDataGridPagination` already accepts in server mode.
 *
 * Pass `total` so an out-of-range deep-linked `page` clamps to the last page once `total` is
 * positive (on mount, or when a late fetch resolves), and the clamped value replaces the raw
 * one in the URL.
 *
 * `page` is 1-based and omitted from the URL at 1; `pageSize` is omitted when it equals
 * `defaultPageSize`. Both writes use `history: "replace"`, matching this add-on's sort/filter/
 * search params — paging through results never pollutes back/forward history. Invalid or
 * out-of-range URL values (negative, fractional, a `pageSize` outside `pageSizeOptions`) clamp to
 * the default rather than throwing, the same posture as this add-on's other parsers.
 *
 * @example
 * const url = useDataGridUrlPagination();
 * const pager = useDataGridPagination({ total: rows.length, pageSizeOptions: url.pageSizeOptions, ...url });
 */
export function useDataGridUrlPagination(options: UseDataGridUrlPaginationOptions = {}): UseDataGridUrlPaginationResult {
  const { prefix, defaultPageSize = DEFAULT_URL_PAGE_SIZE, pageSizeOptions, total } = options;

  const [pageParam, setPageParam] = useQueryState(prefixedKey(prefix, "page"), {
    defaultValue: "",
    parse: (v) => v,
    serialize: (v) => v,
    history: "replace",
  });
  const [pageSizeParam, setPageSizeParam] = useQueryState(prefixedKey(prefix, "pageSize"), {
    defaultValue: "",
    parse: (v) => v,
    serialize: (v) => v,
    history: "replace",
  });

  // the URL value is always gated by a size list, so ?pageSize=100000000 can never force an unbounded fetch
  const resolvedPageSizeOptions: readonly number[] = pageSizeOptions ?? DEFAULT_PAGE_SIZES;
  const rawPage = parsePage(pageParam);
  const pageSize = parsePageSize(pageSizeParam, defaultPageSize, resolvedPageSizeOptions);
  // a 0 total (data loading) must not clamp or write back, or a deep-linked ?page= is wiped before the real total arrives
  const page = total !== undefined && total > 0 ? clampPage(rawPage, total, pageSize) : rawPage;

  // normalize once when the first positive total arrives: write the clamped page back so a deep-linked ?page=999 never revives
  const normalizedRef = useRef(false);
  useEffect(() => {
    if (normalizedRef.current || total === undefined || total <= 0) return;
    normalizedRef.current = true;
    const clamped = clampPage(parsePage(pageParam), total, parsePageSize(pageSizeParam, defaultPageSize, resolvedPageSizeOptions));
    const serialized = serializePage(clamped) || "";
    if (pageParam !== serialized) void setPageParam(serialized || null);
    // oxlint-disable-next-line react-hooks/exhaustive-deps
  }, [total]);

  const onPageChange = useCallback(
    (next: number) => {
      void setPageParam(serializePage(next) || null);
    },
    [setPageParam],
  );

  const onPageSizeChange = useCallback(
    (next: number) => {
      void setPageSizeParam(serializePageSize(next, defaultPageSize) || null);
      // A page number is only valid for the size it was chosen at: a page-size change resets the page to 1 (the URL composition's contract).
      void setPageParam(null);
    },
    [setPageSizeParam, setPageParam, defaultPageSize],
  );

  return useMemo(
    () => ({ page, pageSize, pageSizeOptions: resolvedPageSizeOptions, onPageChange, onPageSizeChange }),
    [page, pageSize, resolvedPageSizeOptions, onPageChange, onPageSizeChange],
  );
}

"use client";

import { useCallback, useEffect, useRef } from "react";
import { useQueryState } from "nuqs";
import {
  useDataGridActions,
  useDataGridAllColumns,
  useDataGridFilterState,
  useDataGridJoinOperator,
  useDataGridSearchText,
  useDataGridSortState,
} from "@/registry/default/components/data-grid/data-grid";
import { isDev, useDataGridSelector, useDataGridStoreApi } from "@/registry/default/components/data-grid/data-grid-sdk";
import type { ColumnLayout } from "@/registry/default/components/data-grid/data-grid";
import { serializeSortState, parseSortState } from "./sort-param";
import { parseLayoutPart, serializeLayoutPart, type UrlLayoutPart } from "./layout-param";
import { serializeFilterState, parseFilterState } from "./filter-param";
import { serializeJoinOperator, parseJoinOperator } from "./join-param";
import { prefixedKey } from "./prefixed-key";

/** Smallest `isAnyOf` / `isNoneOf` list bound for a column with choices, so a link written before a choice was removed still parses. */
const MIN_CHOICE_BOUND = 64;

/** Debounce (ms) between typing in the quick-search box and writing `searchText` to the URL. */
const SEARCH_WRITE_DEBOUNCE_MS = 300;

const DEFAULT_LAYOUT_PARTS: readonly UrlLayoutPart[] = ["order", "hidden"];

const LAYOUT_KEYS: Record<UrlLayoutPart, string> = { order: "cols", hidden: "hide", widths: "widths", pins: "pins" };

function countUnknownLayoutIds(part: Partial<ColumnLayout>, known: ReadonlySet<string>): number {
  const ids = part.order ?? part.hidden ?? Object.keys(part.widths ?? part.pins ?? {});
  return ids.filter((id) => !known.has(id)).length;
}

/** Dev-only warning, core's `warnDev` pattern with this add-on's own prefix (import-boundary rule: add-ons import only from core's block-root barrel). */
function warnDev(message: string): void {
  if (isDev()) console.warn(`[data-grid-url-state] ${message}`);
}

/** Options for {@link useDataGridUrlState}. */
export type UseDataGridUrlStateOptions = {
  /** Namespaces the `sort`/`filter`/`join`/`q` URL keys so multiple grids can coexist on one page. */
  prefix?: string;
  /**
   * Layout parts synced to the URL under `cols` (`order`), `hide` (`hidden`), `widths`, and `pins`.
   * A part is written only while it differs from the layout the grid started with. `[]` turns
   * layout sync off. Default `["order", "hidden"]`.
   */
  layout?: readonly UrlLayoutPart[];
};

/** Result of {@link useDataGridUrlState}. */
export type UseDataGridUrlStateResult = {
  /**
   * Re-applies the current URL params to the store, including the dropped-column warning. Unlike
   * the mount apply, a param missing from the URL clears its sort, filter, join, or search. Call
   * it when the URL changed outside the grid's own writes —
   * back/forward, a framework `setSearchParams`, or a query-only route change — since mount
   * applies exactly once and the store is the source of truth afterwards.
   */
  applyFromUrl: () => void;
};

/**
 * Syncs the grid store's `sortState`/`filterState`/`joinOperator`/`searchText` with the URL via
 * nuqs: applies any URL params to the store once on mount, then writes store changes back to the
 * URL (replacing, never pushing, history entries). Requires a `NuqsAdapter` (or the testing
 * adapter) above it in the tree — nuqs itself is router-agnostic. Search writes are debounced so
 * typing doesn't spam `history.replaceState`; sort/filter/join writes (menu-driven, not
 * keystroke-driven) are immediate. `joinOperator` gets its own `join` param rather than folding
 * into `filter` so a URL generated before this feature existed keeps parsing identically.
 *
 * The URL→store direction runs once on mount; after that the store wins. `applyFromUrl()`
 * re-runs the mount apply when the URL changed outside the grid's own writes.
 */
export function useDataGridUrlState(options: UseDataGridUrlStateOptions = {}): UseDataGridUrlStateResult {
  const { prefix, layout = DEFAULT_LAYOUT_PARTS } = options;
  const layoutParts = layout.join(",");
  const actions = useDataGridActions();
  const allColumns = useDataGridAllColumns();
  const storeApi = useDataGridStoreApi();
  const sortState = useDataGridSortState();
  const filterState = useDataGridFilterState();
  const joinOperator = useDataGridJoinOperator();
  const searchText = useDataGridSearchText();
  const columnLayout = useDataGridSelector((s) => s.columnLayout);

  const [sortParam, setSortParam] = useQueryState(prefixedKey(prefix, "sort"), {
    defaultValue: "",
    parse: (v) => v,
    serialize: (v) => v,
    history: "replace",
  });
  const [filterParam, setFilterParam] = useQueryState(prefixedKey(prefix, "filter"), {
    defaultValue: "",
    parse: (v) => v,
    serialize: (v) => v,
    history: "replace",
  });
  const [joinParam, setJoinParam] = useQueryState(prefixedKey(prefix, "join"), {
    defaultValue: "",
    parse: (v) => v,
    serialize: (v) => v,
    history: "replace",
  });
  const [searchParam, setSearchParam] = useQueryState(prefixedKey(prefix, "q"), {
    defaultValue: "",
    parse: (v) => v,
    serialize: (v) => v,
    history: "replace",
  });
  const layoutQueryOptions = { defaultValue: "", parse: (v: string) => v, serialize: (v: string) => v, history: "replace" } as const;
  const [orderParam, setOrderParam] = useQueryState(prefixedKey(prefix, LAYOUT_KEYS.order), layoutQueryOptions);
  const [hiddenParam, setHiddenParam] = useQueryState(prefixedKey(prefix, LAYOUT_KEYS.hidden), layoutQueryOptions);
  const [widthsParam, setWidthsParam] = useQueryState(prefixedKey(prefix, LAYOUT_KEYS.widths), layoutQueryOptions);
  const [pinsParam, setPinsParam] = useQueryState(prefixedKey(prefix, LAYOUT_KEYS.pins), layoutQueryOptions);
  const layoutParams: Record<UrlLayoutPart, string> = { order: orderParam, hidden: hiddenParam, widths: widthsParam, pins: pinsParam };

  // The nuqs setters are NOT stable across external URL changes (back/forward, setSearchParams,
  // the testing adapter's searchParams prop) — the adapter re-renders and the query hook rebuilds
  // its updater. They must stay out of the write-back effects' dep lists, or an external URL change
  // re-triggers the write-back and stomps the new URL value before applyFromUrl can read it. The
  // refs keep a live handle to the latest setter so the effects only re-run when the STORE state
  // (the actual source of truth) changes.
  const setSortParamRef = useRef(setSortParam);
  setSortParamRef.current = setSortParam;
  const setFilterParamRef = useRef(setFilterParam);
  setFilterParamRef.current = setFilterParam;
  const setJoinParamRef = useRef(setJoinParam);
  setJoinParamRef.current = setJoinParam;
  const setSearchParamRef = useRef(setSearchParam);
  setSearchParamRef.current = setSearchParam;
  const layoutSettersRef = useRef({ order: setOrderParam, hidden: setHiddenParam, widths: setWidthsParam, pins: setPinsParam });
  layoutSettersRef.current = { order: setOrderParam, hidden: setHiddenParam, widths: setWidthsParam, pins: setPinsParam };

  // Reads the current URL params and applies them to the store. Runs once on mount (via the
  // appliedRef guard below) and is exposed as applyFromUrl so a consumer can re-apply after an
  // external URL change (back/forward, setSearchParams, query-only route change).
  const applyUrl = useCallback((keepMountDefaults: boolean) => {
    const initialLayout = storeApi.getInitialState().columnLayout;
    const knownIds = new Set(allColumns.map((c) => c.id));
    const layoutPatch: Partial<ColumnLayout> = {};
    let unknownLayoutIds = 0;
    for (const part of layoutParts ? (layoutParts.split(",") as UrlLayoutPart[]) : []) {
      const parsed = parseLayoutPart(part, layoutParams[part]);
      if (parsed[part] !== undefined) {
        unknownLayoutIds += countUnknownLayoutIds(parsed, knownIds);
        Object.assign(layoutPatch, parsed);
      } else if (!keepMountDefaults) {
        Object.assign(layoutPatch, { [part]: initialLayout[part] });
      }
    }
    if (unknownLayoutIds > 0) warnDev(`dropped ${unknownLayoutIds} URL layout entries for removed columns`);
    // Drop specs a shared link must not apply: a removed column, or one the integrator excluded from sorting/filtering or currently hides. Each drop dev-warns.
    const hidden = new Set(layoutPatch.hidden ?? storeApi.getState().hiddenColumns);
    const usable = (c: (typeof allColumns)[number]) => !hidden.has(c.id);
    const sortableIds = new Set(allColumns.filter((c) => usable(c) && c.sortable !== false).map((c) => c.id));
    const filterableIds = new Set(allColumns.filter((c) => usable(c) && c.filterable !== false).map((c) => c.id));
    const parsedSorts = parseSortState(sortParam);
    const sorts = parsedSorts.filter((spec) => {
      if (sortableIds.has(spec.columnId)) return true;
      warnDev(`dropped URL sort spec for removed, hidden, or unsortable column "${spec.columnId}"`);
      return false;
    });
    const choiceBounds = new Map(
      allColumns.map((c) => {
        const choices = (c.options as { choices?: unknown } | undefined)?.choices;
        return [c.id, Array.isArray(choices) && choices.length > 0 ? Math.max(choices.length, MIN_CHOICE_BOUND) : undefined];
      }),
    );
    const parsedFilters = parseFilterState(filterParam, { maxChoices: (columnId) => choiceBounds.get(columnId) });
    const filters = parsedFilters.filter((spec) => {
      if (filterableIds.has(spec.columnId)) return true;
      warnDev(`dropped URL filter spec for removed, hidden, or unfilterable column "${spec.columnId}"`);
      return false;
    });
    const join = parseJoinOperator(joinParam);
    // On mount an absent param keeps the grid's initial state; a re-apply mirrors the URL, so a removed param clears its state.
    if (sorts.length > 0 || !keepMountDefaults) actions.setSorts(sorts);
    if (filters.length > 0 || !keepMountDefaults) actions.setFilters(filters);
    if (join !== "and" || !keepMountDefaults) actions.setJoinOperator(join);
    if (searchParam || !keepMountDefaults) actions.setSearch(searchParam);

    if (Object.keys(layoutPatch).length > 0) actions.setColumnLayout(layoutPatch);
  }, [actions, allColumns, storeApi, sortParam, filterParam, joinParam, searchParam, layoutParts, orderParam, hiddenParam, widthsParam, pinsParam]);
  const applyFromUrl = useCallback(() => applyUrl(false), [applyUrl]);

  // apply URL -> store exactly once on mount; afterwards the store is the source of truth and
  // this effect's own writes below must not be re-read back as if they were external URL edits.
  const appliedRef = useRef(false);
  useEffect(() => {
    if (appliedRef.current) return;
    appliedRef.current = true;
    applyUrl(true);
    // oxlint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    if (!appliedRef.current) return;
    void setSortParamRef.current(serializeSortState(sortState) || null);
    // oxlint-disable-next-line react-hooks/exhaustive-deps
  }, [sortState]);

  useEffect(() => {
    if (!appliedRef.current) return;
    void setFilterParamRef.current(serializeFilterState(filterState) || null);
    // oxlint-disable-next-line react-hooks/exhaustive-deps
  }, [filterState]);

  useEffect(() => {
    if (!appliedRef.current) return;
    void setJoinParamRef.current(serializeJoinOperator(joinOperator) || null);
    // oxlint-disable-next-line react-hooks/exhaustive-deps
  }, [joinOperator]);

  const lastWrittenLayoutRef = useRef<Partial<Record<UrlLayoutPart, string>> | null>(null);
  useEffect(() => {
    if (!appliedRef.current) return;
    const initialLayout = storeApi.getInitialState().columnLayout;
    const previous = lastWrittenLayoutRef.current;
    const next: Partial<Record<UrlLayoutPart, string>> = {};
    for (const part of layoutParts ? (layoutParts.split(",") as UrlLayoutPart[]) : []) {
      const value = serializeLayoutPart(part, columnLayout);
      next[part] = value === serializeLayoutPart(part, initialLayout) ? "" : value;
      if (previous && part in previous && previous[part] !== next[part]) void layoutSettersRef.current[part](next[part] || null);
    }
    lastWrittenLayoutRef.current = next;
    // oxlint-disable-next-line react-hooks/exhaustive-deps
  }, [columnLayout, layoutParts]);

  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  useEffect(() => {
    if (!appliedRef.current) return;
    if (debounceRef.current) clearTimeout(debounceRef.current);
    debounceRef.current = setTimeout(() => {
      void setSearchParamRef.current(searchText || null);
    }, SEARCH_WRITE_DEBOUNCE_MS);
    return () => {
      if (debounceRef.current) clearTimeout(debounceRef.current);
    };
    // oxlint-disable-next-line react-hooks/exhaustive-deps
  }, [searchText]);

  return { applyFromUrl };
}
